AVL trees suit memory-resident ordered maps that need predictable point and range latency: their balance factor is tightly bounded, so reads remain logarithmic even after adversarial insertion order. That strictness costs more rotations on writes than a red-black tree, which is why many general-purpose ordered maps prefer red-black balancing. Durable database indexes normally use B/B+ trees instead: hundreds of keys fit in each page, so their high fan-out requires far fewer storage I/Os than a binary tree whose child traversal could touch another page at every level.

The implementation turns random updates into sequential immutable flushes. Lookup correctness comes from checking the mutable table and immutable segments newest-first; Bloom filters only skip definite misses, while tombstones are treated as real newest records that stop a search. A full-coverage compaction can discard tombstones because it has already considered every older segment.

```python
import hashlib
import json
import os
import tempfile
from pathlib import Path


class BloomFilter:
    def __init__(self, bits=256, hashes=4, slots=None):
        if bits < 8 or hashes < 1:
            raise ValueError("invalid Bloom-filter dimensions")
        self.bits = bits
        self.hashes = hashes
        self.slots = bytearray((bits + 7) // 8) if slots is None else bytearray.fromhex(slots)

    def positions(self, key: str):
        digest = hashlib.blake2b(key.encode("utf-8"), digest_size=16).digest()
        first = int.from_bytes(digest[:8], "big")
        second = int.from_bytes(digest[8:], "big") | 1
        for number in range(self.hashes):
            yield (first + number * second) % self.bits

    def add(self, key: str) -> None:
        for position in self.positions(key):
            self.slots[position // 8] |= 1 << (position % 8)

    def might_contain(self, key: str) -> bool:
        return all(
            self.slots[position // 8] & (1 << (position % 8))
            for position in self.positions(key)
        )

    def payload(self):
        return {"bits": self.bits, "hashes": self.hashes, "slots": self.slots.hex()}

    @classmethod
    def load(cls, path: Path):
        payload = json.loads(path.read_text())
        return cls(payload["bits"], payload["hashes"], payload["slots"])


def atomic_json(path: Path, payload) -> None:
    temporary = path.with_suffix(path.suffix + ".tmp")
    with temporary.open("w", encoding="utf-8") as file:
        json.dump(payload, file)
        file.flush()
        os.fsync(file.fileno())
    os.replace(temporary, path)


def write_segment(path: Path, rows: dict[str, str | None], bloom_bits=256) -> None:
    temporary = path.with_suffix(path.suffix + ".tmp")
    bloom = BloomFilter(bits=bloom_bits)
    with temporary.open("w", encoding="utf-8") as file:
        for key, value in sorted(rows.items()):
            bloom.add(key)
            file.write(json.dumps([key, value], separators=(",", ":")) + "\n")
        file.flush()
        os.fsync(file.fileno())
    os.replace(temporary, path)
    atomic_json(path.with_suffix(".bf"), bloom.payload())


class Segment:
    def __init__(self, path: Path):
        self.path = path
        self.bloom = BloomFilter.load(path.with_suffix(".bf"))

    def find(self, key: str):
        with self.path.open(encoding="utf-8") as file:
            for line in file:
                current_key, value = json.loads(line)
                if current_key == key:
                    return True, value
                if current_key > key:
                    break
        return False, None

    def rows(self):
        with self.path.open(encoding="utf-8") as file:
            for line in file:
                key, value = json.loads(line)
                yield key, value


class LSMTree:
    def __init__(self, directory: Path, bloom_bits=256):
        self.directory = directory
        self.directory.mkdir(parents=True, exist_ok=True)
        self.bloom_bits = bloom_bits
        self.memtable = {}
        self.segments = []
        self.generation = 0
        self.segment_reads = 0
        self.bloom_skips = 0

    def put(self, key: str, value: str) -> None:
        self.memtable[key] = value

    def delete(self, key: str) -> None:
        self.memtable[key] = None

    def flush(self) -> None:
        if not self.memtable:
            return
        self.generation += 1
        path = self.directory / f"segment-{self.generation:06d}.sst"
        write_segment(path, self.memtable, self.bloom_bits)
        self.segments.insert(0, Segment(path))
        self.memtable = {}

    def get(self, key: str):
        if key in self.memtable:
            return self.memtable[key]
        for segment in self.segments:
            if not segment.bloom.might_contain(key):
                self.bloom_skips += 1
                continue
            self.segment_reads += 1
            found, value = segment.find(key)
            if found:
                return value
        return None

    def compact_all(self) -> None:
        if not self.segments:
            return
        merged = {}
        for segment in self.segments:
            for key, value in segment.rows():
                if key not in merged:
                    merged[key] = value
        live_rows = {key: value for key, value in merged.items() if value is not None}
        obsolete = [(segment.path, segment.path.with_suffix(".bf")) for segment in self.segments]

        self.generation += 1
        replacement = self.directory / f"segment-{self.generation:06d}.sst"
        write_segment(replacement, live_rows, self.bloom_bits)
        self.segments = [Segment(replacement)]
        for data_path, bloom_path in obsolete:
            data_path.unlink()
            bloom_path.unlink()


def demo() -> None:
    with tempfile.TemporaryDirectory() as directory:
        store = LSMTree(Path(directory), bloom_bits=256)
        store.put("tenant-a/checkout", "off")
        store.put("tenant-b/search", "on")
        store.put("tenant-c/theme", "blue")
        store.flush()

        store.put("tenant-a/checkout", "on")
        store.delete("tenant-b/search")
        store.put("tenant-d/payments", "shadow")
        store.flush()

        assert store.get("tenant-a/checkout") == "on"
        assert store.get("tenant-b/search") is None
        assert store.get("tenant-c/theme") == "blue"
        for segment in store.segments:
            assert all(segment.bloom.might_contain(key) for key, _ in segment.rows())

        absent = next(
            key for key in (f"missing-{number}" for number in range(10_000))
            if all(not segment.bloom.might_contain(key) for segment in store.segments)
        )
        store.segment_reads = store.bloom_skips = 0
        assert store.get(absent) is None
        assert store.segment_reads == 0 and store.bloom_skips == 2

        false_positives = sum(
            any(segment.bloom.might_contain(f"probe-{number}") for segment in store.segments)
            for number in range(5_000)
        )
        store.compact_all()
        assert len(store.segments) == 1
        assert dict(store.segments[0].rows()) == {
            "tenant-a/checkout": "on",
            "tenant-c/theme": "blue",
            "tenant-d/payments": "shadow",
        }
        single_segment_store = LSMTree(Path(directory) / "single-segment", bloom_bits=256)
        single_segment_store.delete("tenant-z/retired")
        single_segment_store.flush()
        single_segment_store.compact_all()
        assert len(single_segment_store.segments) == 1
        assert dict(single_segment_store.segments[0].rows()) == {}

        print("PASS segments=", len(store.segments), "false_positives=", false_positives)


if __name__ == "__main__":
    demo()
```

